 "content": "def transform(grid):
    """Color 3 between consecutive non-background markers in each row/column."""
    if not grid:
        return []

    from collections import Counter

    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    width = max(map(len, grid))
    height = len(grid)
    # ARC text payloads may omit trailing background tokens in some rows.
    source = [list(row) + [background] * (width - len(row)) for row in grid]
    out = [row[:] for row in source]

    for r in range(height):
        markers = [c for c, value in enumerate(source[r]) if value != background]
        for left, right in zip(markers, markers[1:]):
            for c in range(left + 1, right):
                if source[r][c] == background:
                    out[r][c] = 3

    for c in range(width):
        markers = [r for r in range(height) if source[r][c] != background]
        for top, bottom in zip(markers, markers[1:]):
            for r in range(top + 1, bottom):
                if source[r][c] == background:
                    out[r][c] = 3

    return out


